theorem t5 {c : ℝ} (mf : Monotone f) (nnc : 0 ≤ c) : Monotone fun x ↦ c * f x  := by
  simp only [←CovariantClass.elim (λ x y, x * y) _ _ nnc, Monotone] at ⊢;
  exact fun a b hk-a ↦ mul_le_mul_of_nonneg_right _ (mf configured to_a_ne_b hk-a)

theorem t12 (h : SetUb s a) (h' : a ≤ b) : SetUb s b  := by
  ext x xs
  exact le_trans (h x xs) h';

theorem mul_right_inj' (ha : a ≠ 0) : a * b = a * c ↔ b = c   := by
  rw [←sub_eq_zero, sub_eq_zero] at ⊢ *;
  exact mul_right_eq_zero_iff ha.mpr
